<template>
  <basic-container>
    <el-card shadow="never" class="settings-card"><template #header><div class="header"><div><b>事件周报</b><p>个人事件总结、自动发送与历史记录</p></div><el-button type="primary" @click="openGenerate">生成指定用户报告</el-button></div></template>
      <div class="settings"><el-switch v-model="globalEnabled" active-text="自动发送周报"/><span>每周</span><el-select v-model="setting.sendDay" style="width:110px"><el-option v-for="(day,i) in weekdays" :key="day" :label="day" :value="i+1"/></el-select><el-select v-model="setting.sendHour" style="width:100px"><el-option v-for="hour in 24" :key="hour" :label="`${hour-1}:00`" :value="hour-1"/></el-select><span class="muted">北京时间 · 汇总上一个完整自然周</span><el-button :loading="saving" @click="saveGlobal">保存设置</el-button><el-button @click="peopleOpen=true;searchUsers('')">个人发送开关</el-button></div>
    </el-card>
    <el-card shadow="never"><div class="filters"><el-input v-model="filters.keyword" placeholder="姓名或账号" clearable style="width:210px" @keyup.enter="search"/><el-date-picker v-model="filters.start" type="date" value-format="YYYY-MM-DD" placeholder="报告开始日期" clearable/><el-select v-model="filters.status" clearable placeholder="生成状态" style="width:140px"><el-option v-for="(label,key) in states" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="load">刷新</el-button></div>
      <el-table :data="records" v-loading="loading" stripe><el-table-column label="用户" min-width="150"><template #default="{row}"><b>{{row.name}}</b><div class="muted">{{row.account}}</div></template></el-table-column><el-table-column label="报告周期" min-width="220"><template #default="{row}">{{row.start}} — {{row.end}}</template></el-table-column><el-table-column label="来源" width="90"><template #default="{row}">{{sources[row.source]||row.source}}</template></el-table-column><el-table-column label="生成状态" width="110"><template #default="{row}"><el-tag :type="row.status==='READY'?'success':row.status==='FAILED'?'danger':'info'">{{states[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="发送情况" min-width="165"><template #default="{row}">{{row.sentTime||'尚未发送'}}</template></el-table-column><el-table-column prop="error" label="失败原因" min-width="130" show-overflow-tooltip/><el-table-column label="操作" min-width="240" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="row.status!=='READY'" @click="preview(row)">查看</el-button><el-button link type="primary" :disabled="row.status!=='READY'" @click="download(row,'pdf')">PDF</el-button><el-button link type="primary" :disabled="row.status!=='READY'" @click="download(row,'docx')">Word</el-button><el-button link type="primary" :disabled="row.status!=='READY'||sending===row.id" @click="send(row)">{{row.sentTime?'重新发送':'发送'}}</el-button><el-button v-if="row.status==='FAILED'" link type="warning" @click="regenerate(row)">重新生成</el-button></template></el-table-column></el-table>
      <el-pagination class="pagination" v-model:current-page="filters.page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/>
    </el-card>
    <el-dialog v-model="generateOpen" title="生成个人事件报告" width="480px" :close-on-click-modal="!generating"><el-form label-position="top"><el-form-item label="用户"><el-select v-model="form.userId" filterable remote :remote-method="searchUsers" placeholder="输入姓名或账号" style="width:100%"><el-option v-for="user in users" :key="user.id" :label="`${user.name}（${user.account}）`" :value="user.id"/></el-select></el-form-item><el-form-item label="日期范围"><el-date-picker v-model="form.range" type="daterange" value-format="YYYY-MM-DD" :disabled-date="future" style="width:100%"/></el-form-item><p class="muted">生成后可先预览，再发送。重新生成会保留之前的报告版本。</p></el-form><template #footer><el-button :disabled="generating" @click="generateOpen=false">取消</el-button><el-button type="primary" :loading="generating" @click="generate">生成并预览</el-button></template></el-dialog>
    <el-dialog v-model="previewOpen" title="报告详情" width="780px"><div v-loading="previewLoading"><div class="report-period">{{detail.start}} — {{detail.end}}</div><div class="report-stats"><div v-for="metric in metrics" :key="metric.key"><span>{{metric.label}}</span><b>{{detail.counts?.[metric.key]||0}}</b></div></div><h3>本周概览</h3><div class="prose" v-html="overviewHtml"></div><p class="insight">{{detail.insight}}</p><h3>进展建议</h3><div v-for="row in detail.progress" :key="row.eventId+row.title" class="report-item"><b>{{row.title}}</b><p>{{row.detail}}</p></div><h3>下周建议</h3><div v-for="row in detail.nextWeek" :key="row.eventId+row.title" class="report-item"><b>{{row.title}}</b><p>{{row.detail}}</p></div><p class="muted">{{detail.scopeNote}}</p><h3>发送记录</h3><el-table :data="detail.deliveries||[]" size="small"><el-table-column prop="createTime" label="发送时间"/><el-table-column prop="actorName" label="操作人"/></el-table></div><template #footer><el-button @click="download(detail,'docx')">下载 Word</el-button><el-button @click="download(detail,'pdf')">下载 PDF</el-button><el-button type="primary" :loading="sending===detail.id" @click="send(detail)">发送到用户对话</el-button></template></el-dialog>
    <el-dialog v-model="peopleOpen" title="个人周报发送设置" width="620px"><el-input v-model="userQuery" placeholder="姓名或账号" @input="searchUsers"/><el-table :data="users"><el-table-column prop="name" label="用户"/><el-table-column prop="account" label="账号"/><el-table-column label="自动接收"><template #default="{row}"><el-switch :model-value="Number(row.enabled)===1" @change="value=>setUser(row,value)"/></template></el-table-column></el-table><p class="muted">个人开启后仍受全局开关控制；不影响管理员手动发送。</p></el-dialog>
  </basic-container>
</template>
<script setup>
import {ref,reactive,onMounted,computed} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {reportRequest,downloadReport} from '@/api/eventReports';
import {marked} from 'marked';import DOMPurify from 'dompurify';
const weekdays=['周一','周二','周三','周四','周五','周六','周日'],states={READY:'已生成',GENERATING:'生成中',PENDING:'等待生成',FAILED:'生成失败',EMPTY:'无事件，未发送'},sources={AUTO:'自动',MANUAL:'手动',QUERY:'问询'};
const metrics=[{key:'completed',label:'已完成'},{key:'active',label:'进行中'},{key:'followUp',label:'待跟进'},{key:'stopped',label:'已停止'}];
const filters=reactive({keyword:'',start:'',status:'',page:1}),setting=reactive({sendDay:1,sendHour:9}),form=reactive({userId:'',range:[]});
const globalEnabled=ref(true),saving=ref(false),records=ref([]),total=ref(0),loading=ref(false),users=ref([]),userQuery=ref(''),peopleOpen=ref(false),generateOpen=ref(false),generating=ref(false),previewOpen=ref(false),previewLoading=ref(false),detail=ref({}),sending=ref('');let userSearch=0;
const overviewHtml=computed(()=>DOMPurify.sanitize(marked.parse(detail.value.overview||'',{gfm:true,breaks:true,headerIds:false,mangle:false}),{USE_PROFILES:{html:true}}));
const requestId=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');const unwrap=response=>response.data.data;
async function load(){loading.value=true;try{const data=unwrap(await reportRequest('list',{...filters,start:filters.start||'',status:filters.status||''}));records.value=data.records;total.value=data.total;}finally{loading.value=false;}}
function search(){filters.page=1;load();}const future=date=>date.getTime()>Date.now();
async function saveGlobal(){saving.value=true;try{await reportRequest('settings/save',{}, {userId:'0',enabled:globalEnabled.value,...setting});ElMessage.success('设置已保存');}finally{saving.value=false;}}
async function searchUsers(keyword=''){const ticket=++userSearch;const data=unwrap(await reportRequest('users',{keyword}));if(ticket===userSearch)users.value=data;}
async function setUser(row,enabled){await reportRequest('settings/save',{}, {userId:row.id,enabled,sendDay:1,sendHour:9});row.enabled=enabled?1:0;}
function openGenerate(){form.userId='';form.range=[];generateOpen.value=true;searchUsers('');}
function regenerate(row){form.userId=row.userId;form.range=[row.start,row.end];generateOpen.value=true;searchUsers(row.account||'');}
async function generate(){if(!form.userId||form.range?.length!==2){ElMessage.warning('请选择用户和日期范围');return;}generating.value=true;try{const data=unwrap(await reportRequest('generate',{}, {userId:form.userId,start:form.range[0],end:form.range[1],requestId:requestId()}));generateOpen.value=false;await load();await preview(data);}finally{generating.value=false;}}
async function preview(row){previewOpen.value=true;previewLoading.value=true;try{detail.value=unwrap(await reportRequest('detail',{id:row.id}));}finally{previewLoading.value=false;}}
async function send(row){try{await ElMessageBox.confirm('将这份报告发送到该用户的小醒对话中。是否发送？','发送报告');}catch{return;}sending.value=row.id;try{await reportRequest('send',{}, {id:row.id,requestId:row.sentTime?requestId():'INITIAL'});ElMessage.success('已发送');await load();if(previewOpen.value)await preview(row);}finally{sending.value='';}}
async function download(row,format){try{await downloadReport(row.id,format);}catch(e){ElMessage.error(e.message||'下载失败');}}
onMounted(async()=>{const data=unwrap(await reportRequest('settings'));globalEnabled.value=Number(data.enabled)===1;setting.sendDay=Number(data.sendDay);setting.sendHour=Number(data.sendHour);await load();});
</script>
<style scoped>.settings-card{margin-bottom:18px}.header,.settings,.filters{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.header{justify-content:space-between}.header b{font-size:20px;color:#253653}.header p,.muted{font-size:12px;color:#8792a6}.filters{margin-bottom:18px}.pagination{margin-top:20px;justify-content:flex-end}.report-period{color:#7889a6;margin-bottom:16px}.report-stats{display:flex;gap:12px}.report-stats>div{flex:1;background:#f1f6ff;border-radius:14px;padding:15px}.report-stats span{display:block;color:#7486a4}.report-stats b{display:block;font-size:27px;color:#397bf3;margin-top:8px}.prose,.report-item p{line-height:1.8;color:#53627a}.insight{background:#f2eeff;border-radius:12px;padding:16px;color:#6b5e9b}.report-item{padding:12px 0;border-bottom:1px solid #eff2f7}.report-item p{margin:6px 0}.report-item b,h3{color:#293e61}.prose :deep(p){margin:8px 0}.prose :deep(ul){padding-left:22px}.prose :deep(strong){color:#293e61}</style>
